using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using System.Linq;
using System.Windows.Forms;
using CircuitoStudio;
internal static class DefinedSourceTests {
 static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Near(double a,double b,string label){Check(Math.Abs(a-b)<1e-9,label);}
 static void Reject(Action a,string label){bool fail=false;try{a();}catch(InvalidDataException){fail=true;}Check(fail,label);}
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static Project Make(){var p=new Project{Earthing="TN-S"};p.Source.LineVoltage=400;var b=new Board{Id="B",Voltage=400};b.Circuits.Add(new Circuit{Id="C",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=10,CableMm2=10});p.Boards.Add(b);return p;}
 [STAThread] public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"defined-source-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var p=Make();var s=p.Source;var c=p.Boards[0].Circuits[0];s.Model=SourceModel.ImpedanciaDefinida;s.DefinedPhaseROhm=.1;s.DefinedPhaseXOhm=.2;s.DefinedNeutralROhm=.05;s.DefinedNeutralXOhm=.02;s.DefinedPEROhm=.03;s.DefinedPEXOhm=.01;s.NetworkReference="Ensaio R/X por fase, N e PE Ω";
  var z=SourceNetwork.Calculate(s);Near(z.TotalROhm.Value,.1,"phase R used for positive sequence");Near(z.TotalXOhm.Value,.2,"phase X used for positive sequence");Near(z.NeutralROhm.Value,.05,"neutral impedance kept separate");Near(z.PEROhm.Value,.03,"PE impedance kept separate");
  double ik=400/(Math.Sqrt(3)*Math.Sqrt(.05)*1000);Near(Engineering.Analyze(p).For(c).FaultOriginKA.Value,ik,"explicit source analytical 3F current");
  s.DefinedNeutralROhm=20;s.DefinedPEROhm=30;Near(Engineering.Analyze(p).For(c).FaultOriginKA.Value,ik,"N and PE not incorrectly added to 3F positive sequence");
  s.DefinedPhaseROhm=0;Near(Engineering.Analyze(p).For(c).FaultOriginKA.Value,400/(Math.Sqrt(3)*.2*1000),"explicit zero resistance distinct from missing");s.DefinedPhaseROhm=null;Check(!SourceNetwork.Calculate(s).TotalROhm.HasValue&&!Engineering.Analyze(p).For(c).FaultOriginKA.HasValue,"missing R does not silently become zero");
  s.DefinedPhaseROhm=0;s.DefinedPhaseXOhm=0;Reject(p.Validate,"zero phase impedance rejected");s.DefinedPhaseROhm=.1;s.DefinedPhaseXOhm=.2;s.DefinedNeutralROhm=-1;Reject(p.Validate,"negative neutral R rejected");s.DefinedNeutralROhm=.05;s.DefinedPEXOhm=double.NaN;Reject(p.Validate,"NaN PE X rejected");s.DefinedPEXOhm=.01;
  s.ShortCircuitKA=10;Reject(p.Validate,"defined source cannot simultaneously infer utility impedance");s.ShortCircuitKA=0;s.TransformerKva=630;Reject(p.Validate,"defined source transformer ambiguity rejected");s.TransformerKva=0;
  string file=Path.Combine(dir,"defined.circuito");p.Save(file);var restored=Project.Load(file);Check(restored.Source.Model==SourceModel.ImpedanciaDefinida&&restored.Source.DefinedNeutralROhm==.05&&restored.Source.DefinedPEROhm==30&&restored.Source.DefinedPEXOhm==.01,"all explicit paths and reference persist");Check(File.ReadAllText(file).Contains("\"FileVersion\":3"),"defined impedance uses guarded format 3");
  string report=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(report.Contains("neutro R/X=")&&report.Contains("PE R/X=")&&report.Contains(s.NetworkReference),"report distinguishes phase N PE and reference");
  s.Model=SourceModel.UPS;s.UPSMode=UPSOperatingMode.Inversor;s.UPSRatedKva=40;s.UPSCurrentLimitKA=.18;s.UPSCurrentLimitSeconds=.2;s.NetworkReference="Folha sintética UPS; limite 180 A por .2 s";z=SourceNetwork.Calculate(s);
  Near(z.UPSCurrentLimitKA.Value,.18,"UPS declared current limit retained");Near(z.UPSCurrentLimitSeconds.Value,.2,"UPS duration retained independently");Check(!z.TotalROhm.HasValue&&!z.TotalXOhm.HasValue,"inverter current limit not converted into Thevenin impedance");Check(!Engineering.Analyze(p).For(c).FaultOriginKA.HasValue,"inverter prospective 3F current remains pending");Check(!s.SupportsConstantImpedanceWaveform&&!s.SupportsVoltageSourceFaults,"inverter not passed to voltage source fault models");
  c.Phases=PhaseMode.Monofasico;c.PhaseLabel="L1";c.Voltage=230.94;c.Protection.FaultLoopOhm=.1;c.Protection.MagneticTripA=100;var study=Engineering.Analyze(p);Check(!study.For(c).FaultLoopKA.HasValue,"UPS does not apply U/Z to supplied fault loop");Check(study.Checks.Single(x=>x.CircuitId==c.Id&&x.Rule.StartsWith("TN:")).Status=="Pendente","UPS fault clearance not falsely approved by U/Z");
  s.UPSCurrentLimitKA=0;s.UPSCurrentLimitSeconds=0;z=SourceNetwork.Calculate(s);Check(!z.UPSCurrentLimitKA.HasValue&&!z.UPSCurrentLimitSeconds.HasValue,"UPS missing limit and duration remain unknown");
  s.ShortCircuitKA=10;Reject(p.Validate,"inverter mode cannot silently include bypass source");s.UPSMode=UPSOperatingMode.Bypass;study=Engineering.Analyze(p);Near(study.For(c).FaultOriginKA.Value,10,"declared bypass uses utility source");Check(s.SupportsConstantImpedanceWaveform&&s.SupportsVoltageSourceFaults,"bypass supports utility equivalent only in declared scenario");Check(SourceNetwork.Calculate(s).Detail.Contains("UPS em bypass declarado"),"bypass interpretation documented");
  s.UPSCurrentLimitKA=.18;s.UPSCurrentLimitSeconds=.2;Near(Engineering.Analyze(p).For(c).FaultOriginKA.Value,10,"bypass does not cap utility at inverter limit");
  s.UPSMode=UPSOperatingMode.Inversor;s.ShortCircuitKA=0;s.UPSCurrentLimitSeconds=-1;Reject(p.Validate,"negative inverter duration rejected");s.UPSCurrentLimitSeconds=.2;s.UPSMode=(UPSOperatingMode)9;Reject(p.Validate,"invalid UPS operating mode rejected");s.UPSMode=UPSOperatingMode.Inversor;
  p.Save(file);restored=Project.Load(file);Check(restored.Source.Model==SourceModel.UPS&&restored.Source.UPSMode==UPSOperatingMode.Inversor&&restored.Source.UPSCurrentLimitKA==.18&&restored.Source.UPSCurrentLimitSeconds==.2&&restored.Source.UPSRatedKva==40,"UPS scenario parameters persist");report=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(report.Contains("fonte limitada em corrente")&&report.Contains("FAQ000280512")&&report.Contains(s.NetworkReference),"UPS report preserves source reference limitations and primary explanation");
  using(var editor=new WizardSourceEditor(new SourceSettings())){var model=Field<ComboBox>(editor,"model");var values=Field<Dictionary<string,TextBox>>(editor,"numbers");var source=Field<SourceSettings>(editor,"source");model.SelectedItem=SourceModel.ImpedanciaDefinida;values["PhaseR"].Text="0";values["PhaseX"].Text="0,2";values["NeutralR"].Text="";values["NeutralX"].Text="";values["PER"].Text="0,03";values["PEX"].Text="0,01";editor.Commit();Check(source.DefinedPhaseROhm==0&&source.DefinedPhaseXOhm==.2&&!source.DefinedNeutralROhm.HasValue,"editor distinguishes zero comma and blank unknown");model.SelectedItem=SourceModel.UPS;Field<ComboBox>(editor,"upsMode").SelectedItem=UPSOperatingMode.Inversor;values["UPSKva"].Text="40";values["UPSLimit"].Text="0,18";values["UPSSeconds"].Text="0,2";editor.Commit();Check(source.Model==SourceModel.UPS&&source.UPSMode==UPSOperatingMode.Inversor&&source.ShortCircuitKA==0&&source.UPSCurrentLimitKA==.18,"editor commits isolated inverter scenario");Field<ComboBox>(editor,"upsMode").SelectedItem=UPSOperatingMode.Bypass;values["Ik"].Text="10";editor.Commit();Check(source.UPSMode==UPSOperatingMode.Bypass&&source.ShortCircuitKA==10,"editor commits bypass source independently");}
  Console.WriteLine("PASS: "+n+" defined source and UPS assertions including path separation, scenarios, pending faults and persistence");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{Directory.Delete(dir,true);}}
}
